// Conditions

/** urn:corpus:bookings:booking:operation:cancel_booking — ensures: output.refund_amount = 0 or current.deposit_amount is present and output.refund_amount <= current.deposit_amount */
export const BookingCancelBookingEnsures1 = (p: { input: BookingBookingRef; current: BookingBooking; output: BookingCancellation }): boolean =>
  (compareDecimal((p.output.refund_amount as string), "0") === 0 || (p.current.deposit_amount !== undefined && compareDecimal((p.output.refund_amount as string), (p.current.deposit_amount as string)) <= 0));

/** urn:corpus:bookings:booking:operation:create_booking — requires: input.party_size < 13 */
export const BookingCreateBookingRequires1 = (p: { input: BookingCreateRequest }): boolean =>
  (p.input.party_size as number) < 13;

/** urn:corpus:bookings:booking:operation:create_booking — requires: input.party_size < 7 or input.deposit_token is present */
export const BookingCreateBookingRequires2 = (p: { input: BookingCreateRequest }): boolean =>
  ((p.input.party_size as number) < 7 || p.input.deposit_token !== undefined);
